class Solution {
public:
    Node* flatten(Node* head) {
        Node* curr = head;
        while (curr) {
            if (curr->child) {
                Node* nxt = curr->next;
                Node* childTail = curr->child;
                while (childTail->next) {
                    childTail = childTail->next;
                }
                curr->next = curr->child;
                curr->child->prev = curr;
                curr->child = nullptr;
                if (nxt) {
                    childTail->next = nxt;
                    nxt->prev = childTail;
                }
            }
            curr = curr->next;
        }
        return head;
    }
};

class Solution {
    public Node flatten(Node head) {
        Node curr = head;
        while (curr != null) {
            if (curr.child != null) {
                Node nxt = curr.next;
                Node childTail = curr.child;
                while (childTail.next != null) {
                    childTail = childTail.next;
                }
                curr.next = curr.child;
                curr.child.prev = curr;
                curr.child = null;
                if (nxt != null) {
                    childTail.next = nxt;
                    nxt.prev = childTail;
                }
            }
            curr = curr.next;
        }
        return head;
    }
}

var flatten = function(head) {
    let curr = head;
    while (curr) {
        if (curr.child) {
            const nxt = curr.next;
            let childTail = curr.child;
            while (childTail.next) {
                childTail = childTail.next;
            }
            curr.next = curr.child;
            curr.child.prev = curr;
            curr.child = null;
